    "ward.0-to-a-break-in-the": "0 முதல் {v} வரை. கோட்டில் உள்ள இடைவெளி என்பது மதிப்பு இல்லாத ஒரு bucket ஆகும், பூஜ்ஜியம் அல்ல.",
