    "ward.no-connection-saved-on-this-device": "இணைப்பு இல்லை. {label} இந்த சாதனத்தில் சேமிக்கப்பட்டது, இன்னும் அனுப்பப்படவில்லை: அனுப்பப்படும் வரை இது பதிவில் இருக்காது, இணைப்பு திரும்பும்போது இது அனுப்பப்படும்.",
    "ward.no-connection-your-decision-could-not": "இணைப்பு இல்லை: உங்கள் முடிவு பதிவு செய்யப்பட முடியவில்லை, எனவே எதுவும் மாறவில்லை. ஆன்லைனில் இருக்கும்போது மீண்டும் முயற்சிக்கவும்.",
    "ward.no-consent-has-been-recorded-for": "இந்த நோயாளிக்கு சம்மதம் எதுவும் பதிவு செய்யப்படவில்லை.",
    "ward.no-contrast-reaction-is-recorded-that": "காண்ட்ராஸ்ட் எதிர்வினை எதுவும் பதிவு செய்யப்படவில்லை. பதிவில் உள்ள தகவல் இதுவே, வேறு எங்கும் எதுவும் நடக்கவில்லை என்பதற்கான உத்தரவாதம் அல்ல.",
    "ward.no-creatinine-on-record": "பதிவில் கிரியேட்டினின் அளவு இல்லை.",
    "ward.no-cultures-in-progress": "வளர்ச்சியில் எந்த கல்ச்சரும் இல்லை.",
