    "ward.no-one-click-transfuse-both-checkers": "ஒரே கிளிக்கில் குருதி ஏற்ற முடியாது: இரண்டு சரிபார்ப்பாளர்களும் இரண்டு ஸ்கேன்களும் கட்டாயம் தேவை.",
    "ward.no-one-click-transfuse-both-checkers2": "NO ONE-CLICK TRANSFUSE. இரு சரிபார்ப்பாளர்கள் மற்றும் இரு ஸ்கேன்களும் தேவை; இணக்கத்தன்மை ஸ்கேன் செய்யப்பட்டவற்றிலிருந்து மட்டுமே பெறப்படும், crossmatch பதிவிலிருந்து ஒருபோதும் நம்பப்படாது.",
