    "ward.saved-as-a-note-on-the2": "நோயாளியின் காலவரிசையில் ஒரு குறிப்பாக சேமிக்கப்பட்டது. காலியாக விடப்பட்ட தமனி அறிவிக்கப்படவில்லை என்று எழுதப்படும், ஒருபோதும் இயல்பானது என்று எழுதப்படாது.",
    "ward.saved-but-the-critical-result-alert": "சேமிக்கப்பட்டது, ஆனால் இந்த நேர்மறை இரத்த வளர்ப்புக்கான கவலைக்கிடமான முடிவு எச்சரிக்கையைத் திறக்க முடியவில்லை. உடனடியாக வார்டை தொலைபேசியில் தொடர்பு கொள்ளவும்.",
    "ward.saved-on-this-device": "இந்த சாதனத்தில் சேமிக்கப்பட்டது",
    "ward.saved-on-this-device-not-yet": "இந்த சாதனத்தில் சேமிக்கப்பட்ட {waiting}, இன்னும் அனுப்பப்படவில்லை",
    "ward.saved-with-still-blank-it-is": "{join} இன்னும் காலியாக உள்ள நிலையில் சேமிக்கப்பட்டது. இது முழுமையடையாததாக பதிவில் உள்ளது.",
    "ward.saved2": "சேமிக்கப்பட்டது",
    "ward.say-how-often-this-infusion-is": "இந்த infusion எவ்வளவு அடிக்கடி வழங்கப்படுகிறது என்று குறிப்பிடவும் (எடுத்துக்காட்டாக STAT, OD அல்லது BD). இதன் duration ஒரு frequency அல்ல.",
    "ward.say-started-rate-changed-paused-resumed": "தொடங்கப்பட்டது, அளவு மாற்றப்பட்டது, இடைநிறுத்தப்பட்டது, மீண்டும் தொடங்கப்பட்டது அல்லது நிறுத்தப்பட்டது என்று கூறவும்.",
    "ward.say-what-actually-happened-ordering-a": "உண்மையில் என்ன நடந்தது என்று கூறவும் - ஒரு பொருளை ஆர்டர் செய்வது அதைச் செய்வது இல்லை.",
    "ward.say-what-establishes-these-are-the": "இவர்கள் ஒரே நபர்தான் என்பதை எது உறுதிப்படுத்துகிறது என்று கூறவும் (குறைந்தது ஒரு சிறிய வாக்கியம்).",
    "ward.say-what-needs-checking": "என்ன சரிபார்க்கப்பட வேண்டும் என்று கூறவும்.",
    "ward.say-what-the-emergency-is-in": "அவசரநிலை என்னவென்று உங்கள் சொந்த வார்த்தைகளில் கூறவும் - குறைந்தபட்சம் 10 எழுத்துகள்.",
    "ward.say-what-the-query-is-so": "கேள்வி என்னவென்று கூறவும், இதனால் வார்டு அதற்கேற்ப செயல்பட முடியும்.",
    "ward.say-what-this-is-about": "இது எதைப் பற்றியது என்று கூறவும்.",
    "ward.say-what-this-plan-is-for": "இந்தத் திட்டம் எதற்காக என்று கூறவும்.",
    "ward.say-what-was-done-clearing-it": "என்ன செய்யப்பட்டது என்று கூறவும். எந்தவொரு காரணமும் இல்லாமல் பட்டியலிலிருந்து இதை நீக்குவது, நோயாளிக்கு மருந்துச்சீட்டு இல்லாமலும், காரணம் என்னவென்று தெரியாமலும் விட்டுவிடும்.",
    "ward.say-what-was-seen-the-impression": "என்ன பார்க்கப்பட்டது என்று கூறவும்; மதிப்பீடு தொடர்ந்து வரலாம்.",
    "ward.say-when-it-was-done": "இது எப்போது செய்யப்பட்டது என்று கூறவும்.",
    "ward.say-when-the-plan-will-be": "இந்தத் திட்டம் அடுத்து எப்போது பரிசீலிக்கப்படும் என்று கூறவும்.",
    "ward.say-when-this-plan-will-be": "இந்தத் திட்டம் எப்போது பரிசீலிக்கப்படும் என்று கூறவும்.",
    "ward.say-where-on-the-body": "உடலில் எங்கு என்று கூறவும்.",
    "ward.say-which-one-this-is-about": "இது எதைப் பற்றியது என்று கூறவும்.",
    "ward.say-which-patient-by-mrn": "MRN மூலம் எந்த நோயாளி என்று கூறவும்.",
    "ward.say-which-procedure-was-done": "எந்த நடைமுறை செய்யப்பட்டது என்று கூறவும்.",
    "ward.say-who-performed-it": "இதை யார் செய்தார் என்று கூறவும்.",
    "ward.say-who-this-is-being-ordered": "இது யாரிடமிருந்து ஆர்டர் செய்யப்படுகிறது என்று கூறவும்.",
    "ward.say-why-it-is-needed": "இது ஏன் தேவைப்படுகிறது என்று கூறவும்.",
    "ward.say-why-this-patient-is-being": "இந்த நோயாளிக்கு ஏன் மீண்டும் ட்ரையாஜ் செய்யப்படுகிறது என்று கூறவும்.",
    "ward.say-why-this-patient-needs-to": "இந்த நோயாளி ஏன் வர வேண்டும் என்று கூறவும்.",
    "ward.say-why-your-entry-should-stand": "உங்கள் பதிவு ஏன் இருக்க வேண்டும் என்று சில வார்த்தைகளில் கூறவும். இது உங்கள் முடிவுடன் பதிவு செய்யப்படும்.",
    "ward.scan-asset-tag": "சொத்து டேக்கை ஸ்கேன் செய்யவும்",
    "ward.scan-or-enter-the-patient-s": "சரியான நோயாளிதான் என்பதை உறுதிப்படுத்த, நோயாளியின் கைப்பட்டை பார்கோடு/MRN ஐ ஸ்கேன் செய்யவும் அல்லது உள்ளிடவும்:",
    "ward.scan-or-type-the-code-on": "பட்டையில் உள்ள குறியீட்டை ஸ்கேன் செய்யவும் அல்லது தட்டச்சு செய்யவும்.",
