    "ward.shortcuts-only-move-around-nothing-is": "குறுக்குவழிகள் நகர்த்துவதற்கு மட்டுமே பயன்படும். விசைப்பலகையில் இருந்து எதுவும் சேமிக்கப்படவோ, வழங்கப்படவோ அல்லது கையொப்பமிடப்படவோ இல்லை, மேலும் நீங்கள் ஒரு புலத்தில் தட்டச்சு செய்யும்போது எந்த குறுக்குவழியும் செயல்படாது.",
