    "ward.cover-setup-no-shifts": "பணியாளர் பணிச்சுழற்சியில் (Staff rota) எந்த ஷிஃப்ட்டும் இல்லை. Staff rota-வில், ஒவ்வொரு வார்டுக்கும் ஒரு ஷிஃப்ட்டை வரையறுத்து, நர்ஸ்கள், ரெசிடென்ட்கள் மற்றும் கன்சல்டண்ட்களை ஒதுக்கவும். அதுவரை ஆபத்தான முடிவின் லெவல் 2 எச்சரிக்கை, தம்மைப் பணியில் உள்ளதாகக் குறிப்பவர்களை மட்டுமே சென்றடையும்.",
    "ward.cover-setup-assign": "{n} வார்டுகளில் இப்போது இயங்கும் ஷிஃப்ட்டில் யாரும் ஒதுக்கப்படவில்லை. Staff rota-வில், இன்றைய ஷிஃப்டுகளுக்கு நர்ஸ்கள், ரெசிடென்ட்கள் மற்றும் கன்சல்டண்ட்களை ஒதுக்கவும், அல்லது அவர்களைப் பணியில் உள்ளதாகக் குறிக்கச் சொல்லவும்.",
