    "ward.qm-no-escalation-window": "இந்த மருத்துவமனையில் escalation window கட்டமைக்கப்படவில்லை, எனவே ஒப்பிட எந்த வரம்பும் (threshold) இல்லை. அமைப்பில் (organisation) wardsynq.criticalEscalation ஐ அமைக்கவும்.",
    "ward.qm-no-due-times": "இந்தக் காலத்தில் வழங்கப்பட்ட {given} டோஸ்களில் எதுவும் எப்போது கொடுக்கப்பட வேண்டும் (due time) என்ற பதிவைக் கொண்டிருக்கவில்லை, எனவே தாமதத்தைக் கணக்கிட முடியாது. 2026-09-07 க்கு முன் எழுதப்பட்ட Administration பதிவுகளில் dueAt இல்லை.",
    "ward.qm-no-allergy-status-record": "WardSynQ ஆல் \"கேட்கப்பட்டது, ஒவ்வாமை எதுவும் இல்லை\" என்பதைப் பதிவுசெய்ய முடியாது, எனவே allergy பதிவு இல்லாத நோயாளிக்கும், யாரும் கேட்காத நோயாளிக்கும் இடையே வித்தியாசம் காண முடியாது. இங்குள்ள எந்த விகிதமும் நோயாளியிடம் கேட்காத வார்டுக்கு நல்ல ஆவணமாக்கல் இருப்பதாகவே காட்டும். இதற்கு கணக்கீடு அல்ல, no-known-allergies பதிவு தேவை.",
    "ward.qm-type-unreadable": "{type} பதிவுகளைப் படிக்க முடியவில்லை: {why}",
    "ward.qm-records-unreadable": "பதிவுகளைப் படிக்க முடியவில்லை: {why}",
    "ward.qm-no-antibiotic-list": "ஆண்டிபயாடிக் பட்டியல் கட்டமைக்கப்படவில்லை. இந்த மருத்துவமனை கணக்கிடும் மருந்துப் பெயர்கள் அல்லது குறியீடுகளுக்கு அமைப்பில் (organisation) wardsynq.antibiotics ஐ அமைக்கவும்.",
    "ward.qm-administrations-unreadable": "Administration அல்லது encounter பதிவுகளைப் படிக்க முடியவில்லை.",
    "ward.qm-reports-unreadable": "Report அல்லது request பதிவுகளைப் படிக்க முடியவில்லை.",
    "ward.qm-no-beds-configured": "இந்த மருத்துவமனைக்கு படுக்கைகள் எதுவும் கட்டமைக்கப்படவில்லை (wardsynq.beds), எனவே கிடைக்கக்கூடிய படுக்கை-நாட்களின் பகுதி (denominator) இல்லை.",
    "ward.qm-too-few-cases-one": "இந்தக் காலத்தில் {cases} கேஸ். விகிதமாகப் படிக்க மிகவும் குறைவு.",
    "ward.qm-too-few-cases": "இந்தக் காலத்தில் {cases} கேஸ்கள். விகிதமாகப் படிக்க மிகவும் குறைவு.",
    "ward.qm-no-bed-days": "இந்தக் காலத்தில் occupied bed-days இல்லை, எனவே விகிதம் எதுவுமில்லை.",
    "ward.qm-below-minimum": "தகுதியான {denominator} கேஸ்கள் குறைந்தபட்ச அளவான {minimum} ஐ விடக் குறைவாக உள்ளன; இங்குள்ள சதவீதம் மிகப்பெரிய மக்கள்தொகையின் சதவீதங்களுடன் ஒப்பிடப்படும், மேலும் அவை வெவ்வேறு வகையான எண்கள் என்று எதுவும் தெரிவிக்காது",
    "ward.qm-beds-not-subtracted": "கிடைக்கக்கூடிய படுக்கைகள் என்பவை கட்டமைக்கப்பட்ட படுக்கைப் பட்டியலாகும்; முடக்கப்பட்ட அல்லது மூடப்பட்ட படுக்கைகள் கழிக்கப்படவில்லை.",
    "ward.qm-deaths-source": "இறப்புகள் பதிவுசெய்யப்பட்ட இறப்பிலிருந்து (Patient.deceased) அல்லது discharge disposition இலிருந்து படிக்கப்படுகின்றன. இரண்டும் இல்லாத தங்குதல் தரவு விடுபட்டதாக விலக்கப்பட்டு, கணக்கிடப்படுகிறது.",
