    "ward.inv-list-failed": "பரிசோதனைகளின் பட்டியலை லோட் செய்ய முடியவில்லை. பட்டியலில் இல்லை என்ற காரணத்தைக் குறிப்பிட்டு இன்னமும் பரிசோதனையை ஆர்டர் செய்யலாம்.",
