    "ward.cam-scanned": "புலத்தில் ஸ்கேன் செய்யப்பட்டது. அதைச் சரிபார்த்து, பார்கோடு ஸ்கேனருக்குப் பிறகு நீங்கள் அழுத்தும் அதே பொத்தானை அழுத்தவும்.",
