    "ward.cam-denied": "கேமரா அனுமதிக்கப்படவில்லை. உலாவி அமைப்பில் அதை அனுமதிக்கவும், அல்லது பார்கோடு ஸ்கேனரைப் பயன்படுத்தவும் அல்லது குறியீட்டை டைப் செய்யவும்.",
    "ward.cam-failed": "கேமராவைத் தொடங்க முடியவில்லை. பார்கோடு ஸ்கேனரைப் பயன்படுத்தவும் அல்லது குறியீட்டை டைப் செய்யவும்.",
    "ward.label-print-failed": "இந்த உலாவியால் பிரிண்டிங்கைத் திறக்க முடியவில்லை. எதுவும் பிரிண்ட் செய்யப்படவில்லை.",
    "ward.label-dialog-wristband": "கைப்பட்டைக்கான பிரிண்ட் டயலாக் திறக்கப்பட்டுள்ளது.",
    "ward.label-dialog-slip": "ID ஸ்லிப்பிற்கான பிரிண்ட் டயலாக் திறக்கப்பட்டுள்ளது.",
    "ward.label-dialog-specimen": "டியூப் லேபிளுக்கான பிரிண்ட் டயலாக் திறக்கப்பட்டுள்ளது.",
    "ward.label-dialog-pharmacy": "ஃபார்மசி லேபிளுக்கான பிரிண்ட் டயலாக் திறக்கப்பட்டுள்ளது.",
    "ward.label-patient-unread": "நோயாளியின் விவரங்களைப் படிக்க முடியவில்லை. எதுவும் பிரிண்ட் செய்யப்படவில்லை.",
    "ward.label-unavailable": "இந்த பதிப்பில் லேபிள் பிரிண்டிங் வசதி இல்லை.",
    "ward.label-allergies-unread": "ஒவ்வாமை விவரங்களைப் படிக்க முடியாததால், கைப்பட்டை பிரிண்ட் செய்யப்படவில்லை. வாசிப்பு தோல்வியடைந்ததால் எதையும் பதிவு செய்யப்படவில்லை என்று பட்டையில் ஒருபோதும் கூறக்கூடாது. மீண்டும் முயற்சிக்கவும்.",
    "ward.label-no-band-value": "இந்த நோயாளிக்கு பிரிண்ட் செய்ய MRN அல்லது பட்டைக் குறியீடு இல்லை. எதுவும் பிரிண்ட் செய்யப்படவில்லை.",
    "ward.label-band-not-bedside": "இதன் குறியீடு பதிவில் உள்ள நோயாளியின் பட்டையாகும், இது மருந்து மற்றும் மாதிரியின் ஸ்கேன்கள் ஒப்பிடும் MRN அல்ல: அந்த ஸ்கேன்கள் இதை நிராகரிக்கும்.",
    "ward.label-band-tags-unread": "ஏற்கனவே வழங்கப்பட்ட பேண்டுகளைப் படிக்க முடியவில்லை, எனவே இந்த பேண்டில் MRN உள்ளது. நோயாளி அணிந்திருக்கும் பேண்டுடன் இதைச் சரிபார்க்கவும்.",
    "ward.label-no-accession": "இந்த மாதிரிக்கு பதிவில் accession number இல்லை, எனவே டியூப் லேபிள் எதுவும் பிரிண்ட் செய்யப்படவில்லை.",
    "ward.label-not-collected": "அந்த மாதிரி சேகரிக்கப்பட்டதாகப் பதிவு செய்யப்படவில்லை, எனவே பிரிண்ட் செய்ய டியூப் லேபிள் எதுவும் இல்லை.",
    "ward.label-dispense-unknown": "அந்த விநியோகம் இனி இந்தத் திரையில் இல்லை. ஃபார்மசி திரையை ரீலோட் செய்யவும். எதுவும் பிரிண்ட் செய்யப்படவில்லை.",
    "ward.label-order-unknown": "இந்த விநியோகத்திற்கான ஆர்டர் வரிசையில் இல்லை, எனவே இதன் டோஸ், வழி மற்றும் அதிர்வெண் இங்கு தெரியவில்லை. எதுவும் பிரிண்ட் செய்யப்படவில்லை.",
    "ward.label-settings-unread": "மருத்துவமனையின் லேபிள் அமைப்புகள் லோட் ஆகவில்லை. வார்டை ரீலோட் செய்து மீண்டும் முயற்சிக்கவும். எதுவும் பிரிண்ட் செய்யப்படவில்லை.",
    "ward.label-offer-admission": "{who} சேர்க்கப்பட்டார். Wristband மற்றும் ID slip-ஐ இப்போது Print செய்யவும்.",
    "ward.label-offer-specimen": "{test} சேகரிக்கப்பட்டது. Bedside-லிருந்து அகற்றுவதற்கு முன் tube-ல் label ஒட்டவும்.",
    "ward.label-offer-pharmacy": "{drug} விநியோகிக்கப்பட்டது. சப்ளைக்கான label-ஐ Print செய்யவும்.",
    "ward.scan-or-type-the-tube-label": "Tube-ல் உள்ள label-ஐ scan செய்யவும் அல்லது type செய்யவும்.",
    "ward.no-tube-in-transit-carries-that": "இந்த board-ல் உள்ள எந்த sample transit-லும் அந்த label இல்லை. எதுவும் பெறப்படவில்லை.",
    "ward.cam-point-at-code": "கேமராவை barcode அல்லது QR code-ஐ நோக்கி வைக்கவும்.",
    "ward.lab-stock-item": "பொருள்",
