    "ward.lab-an-preliminary": "தற்காலிகமானது",
    "ward.lab-an-corrected": "திருத்தப்பட்டது",
    "ward.lab-an-not-mapped": "map செய்யப்படவில்லை: {code}",
    "ward.lab-an-qc-unread": "இந்த analyser-ன் QC நிலையைக் படிக்க முடியவில்லை. அது load ஆகும் வரை release செய்ய வேண்டாம்.",
    "ward.lab-an-qc-blocked": "{tests}-க்கு QC நிராகரிக்கப்பட்டது. Quality control-ல் சரிசெய்யும் நடவடிக்கையைப் பதிவுசெய்யவும், அல்லது காரணத்துடன் override செய்யவும்.",
    "ward.lab-an-no-sample": "பதிவில் உள்ள எந்த sample-உம் இந்த tube உடன் பொருந்தவில்லை.",
    "ward.lab-an-release": "வெளியிடு",
    "ward.lab-an-none-mapped": "இந்தக் குறியீடுகள் எதுவுமே மருத்துவமனை பரிசோதனையுடன் இணைக்கப்படவில்லை (mapped), எனவே எதையும் வெளியிட் (release) முடியாது. ஒரு நிர்வாகி इनको Integrations இன் கீழ் இணைக்க வேண்டும்.",
    "ward.lab-an-dismiss": "வெளியிட வேண்டாம்",
    "ward.lab-an-title": "Analysers இலிருந்து",
    "ward.lab-an-pending": "Analysers இலிருந்து, வெளியிட காத்திருக்கிறது &middot; {n}",
    "ward.lab-an-none": "காத்திருக்கும் analyser முடிவுகள் எதுவும் இல்லை.",
    "ward.lab-an-unmatched": "Analysers இலிருந்து, மாதிரிக்கு (sample) பொருந்தவில்லை &middot; {n}",
    "ward.lab-qc-override-q": "நிராகரிக்கப்பட்ட QC ஓட்டம் இந்த analyser மற்றும் பரிசோதனையைத் தடுக்கிறது. இருப்பினும் இதை விடுவிப்பது (release) ஏன் பாதுகாப்பானது?",
    "ward.lab-qc-override-need": "ஒரு override க்கு காரணம் தேவை.",
    "ward.lab-qc-override-ok": "Override செய்து வெளியிடவும்",
    "ward.lab-qc-override-short": "கூடுதலாகக் கூறவும்: ஒரு override காரணம் குறைந்தது 10 எழுத்துகள் இருக்க வேண்டும்.",
    "ward.lab-an-released-unmarked": "முடிவு chart க்கு வெளியிடப்பட்டது, ஆனால் இந்த analyser வரிசையை முடிந்ததாகக் குறிக்க முடியவில்லை, மேலும் பட்டியலில் இருக்கலாம். இதை மீண்டும் வெளியிட வேண்டாம்.",
    "ward.lab-an-release-unknown": "Server இலிருந்து பதில் இல்லை. முடிவு வெளியிடப்பட்டிருக்கலாம் அல்லது வெளியிடப்படாமல் இருக்கலாம்; மீண்டும் முயற்சிக்கும் முன் board ஐ refresh செய்யவும்.",
    "ward.lab-an-dismiss-q": "இந்த முடிவு ஏன் வெளியிடப்படவில்லை (மறு ஓட்டம், மாதிரி நிராகரிக்கப்பட்டது, நம்முடைய மாதிரி இல்லை)?",
    "ward.lab-an-dismiss-need": "இந்த முடிவு ஏன் வெளியிடப்படவில்லை என்று கூறவும்.",
    "ward.lab-an-dismissed": "Bench இலிருந்து அகற்றப்பட்டது. எதுவும் வெளியிடப்படவில்லை.",
