    "ward.reg-abdm-inactive": "இந்த மருத்துவமனையின் ABDM சுயவிவரம் (profile) முடக்கப்பட்டுள்ளது.",
    "ward.reg-abdm-not-linked": "இந்த மருத்துவமனை இன்னும் ABDM உடன் இணைக்கப்படவில்லை. ABDM ஆனது StewardMD bridge உடன் இந்த வசதியை இணைத்து, முதலில் ஒரு HIP ID வழங்க வேண்டும்.",
