    "ward.reg-abdm-check-failed": "இந்த மருத்துவமனை ABDM-உடன் இணைக்கப்பட்டுள்ளதா என்பதைச் சரிபார்க்க முடியவில்லை. கீழே தட்டச்சு செய்யப்பட்ட ABHA சரிபார்க்கப்படாமல், தட்டச்சு செய்தபடியே பதிவு செய்யப்படுகிறது.",
    "ward.reg-abdm-typed-not-verified": "கீழே தட்டச்சு செய்யப்பட்ட ABHA சரிபார்க்கப்படாமல், தட்டச்சு செய்தபடியே பதிவு செய்யப்படுகிறது.",
    "ward.reg-abdm-already-linked": "இந்த ABHA ஏற்கனவே இந்த மருத்துவமனையில் நோயாளி {mrn}-க்கு உரியது. புதிய பதிவைச் செய்வதற்குப் பதிலாக அந்தப் பதிவைத் திறக்கவும்.",
