    "ward.pkg-attach-text": "பின்னர் விலைப்பட்டியல் மாறினாலும், தங்கியிருத்தல் இப்போது தேர்ந்தெடுக்கப்பட்ட பேக்கேஜ் பதிப்பையே தக்கவைத்துக்கொள்ளும். ஏற்கனவே தனித்தனி பொருள் கட்டணம் (itemised bill) உள்ள தங்கியிருப்பை பேக்கேஜில் சேர்க்க முடியாது.",
