    "site.shell.signInError.unauthorizedDomain": "இந்த முகவரிக்கு கூகுள் உள்நுழைவு இன்னும் செயல்படுத்தப்படவில்லை. மேலே உள்ள உங்கள் மின்னஞ்சல் மற்றும் கடவுச்சொல் மூலம் உள்நுழையவும், அது இப்போது செயல்படும். கூகுளை இயக்க, ஒரு நிர்வாகி StewardMD Firebase திட்டத்தின் அங்கீகரிக்கப்பட்ட களங்களில் {host} ஐச் சேர்க்க வேண்டும்.",
    "site.shell.signInError.popupBlocked": "உங்கள் உலாவி கூகுள் உள்நுழைவு சாளரத்தைத் தடுத்துள்ளது. இந்த தளத்திற்கான பாப்-அப்களை அனுமதிக்கவும், அல்லது மேலே உள்ள உங்கள் மின்னஞ்சல் மற்றும் கடவுச்சொல் மூலம் உள்நுழையவும்.",
