    "site.shell.home.tile.emergencyadmin.title": "அவசர அணுகல்",
    "site.shell.home.tile.emergencyadmin.sub": "அறிவிப்புகள், பிரேக்-கிளாஸ் பதிவு, நல்லிணக்கம்",
    "site.shell.home.tile.incidents.title": "பாதுகாப்பு மற்றும் சம்பவங்கள்",
    "site.shell.home.tile.incidents.sub": "அறிக்கையைத் தாக்கல் செய்; பாதுகாப்பு அதிகாரிகளுக்கான ட்ரையாஜ், RCA மற்றும் CAPA",
    "site.shell.home.tile.safetyinbox.title": "பாதுகாப்பு இன்பாக்ஸ்",
    "site.shell.home.tile.safetyinbox.sub": "வார்டில் ஒரு நபர் தேவைப்படும் அனைத்தும், மிகவும் அவசரமானது முதலில்",
    "site.shell.home.tile.breakglass.title": "அவசர அணுகல்",
    "site.shell.home.tile.breakglass.sub": "அவசரக்காலத்தில் நோயாளிக்கு பிரேக் கிளாஸ் செய்து, அது பயன்படுத்தப்பட்ட ஒவ்வொரு முறையும் மதிப்பாய்வு செய்யவும்",
    "site.shell.home.tile.handovers.title": "ஷிஃப்ட் ஒப்படைப்பு",
    "site.shell.home.tile.handovers.sub": "அடுத்த ஷிஃப்டிற்கு நோயாளியை ஒப்படைக்கவும், உங்களுக்காக காத்திருப்பவர்களை எடுத்துக் கொள்ளவும்",
    "site.shell.home.tile.admreqs.title": "படுக்கைக்காக காத்திருக்கிறது",
    "site.shell.home.tile.admreqs.sub": "படுக்கை கோரவும், யார் எவ்வளவு நேரமாகக் காத்திருக்கிறார்கள் என்று பார்க்கவும்",
    "site.shell.home.tile.nurseworklist.title": "செவிலியர் பணிப்பட்டியல்",
    "site.shell.home.tile.nurseworklist.sub": "ஒவ்வொரு நோயாளி: தாமதமான அளவுகள், அடுத்து கொடுக்க வேண்டியவை, ஆரம்ப எச்சரிக்கை மதிப்பெண்",
    "site.shell.home.tile.surveillance.title": "கண்காணிப்பு",
    "site.shell.home.tile.surveillance.sub": "அதிகரிக்கும் NEWS2, செப்சிஸ் பரிசோதனைகள், மோசமடையும் ஆய்வக முடிவுகள், ஆதாரத்துடன் தாமதமான பராமரிப்பு",
    "site.shell.home.tile.referralinbox.title": "பரிந்துரை இன்பாக்ஸ்",
    "site.shell.home.tile.referralinbox.sub": "உங்கள் சிறப்புப் பிரிவுக்காகக் காத்திருக்கும் பரிந்துரைகள் மற்றும் நீங்கள் அனுப்பியவை",
    "site.shell.home.tile.mpi.title": "இரட்டைப் பதிவுகள்",
    "site.shell.home.tile.mpi.sub": "இரண்டு பதிவுகள் இருக்கக்கூடிய நோயாளியைக் கண்டறிந்து, காரணத்துடன் அவற்றை இணைக்கவும்",
    "site.shell.home.tile.approvals.title": "ஒப்புதல்கள்",
    "site.shell.home.tile.approvals.sub": "கட்டுப்படுத்தப்பட்ட மருந்துக்கான ஒப்புதலைக் கோரவும், காத்திருப்பவற்றுக்கு ஒப்புதல் அளிக்கவும்",
    "site.shell.home.tile.purchasing.title": "கொள்முதல்",
    "site.shell.home.tile.purchasing.sub": "விநியோகஸ்தர் ஆர்டரை உருவாக்கி, ஒப்புதல் பெற்று, சரக்கு வந்ததும் பதிவு செய்யவும்",
    "site.shell.home.tile.downtime.title": "டவுன்டைம் பேக்",
    "site.shell.home.tile.downtime.sub": "நெட்வொர்க் முடக்கத்தின் போது அச்சிடக்கூடிய வார்டு நிலை",
    "site.shell.home.tile.patients.title": "நோயாளிகள்",
    "site.shell.home.tile.patients.sub": "MRN மூலம் தேடவும், புதிய நோயாளியைப் பதிவு செய்யவும், சார்ட்டைத் திறக்கவும்",
    "site.shell.home.tile.portalAccess.title": "நோயாளி போர்ட்டல்",
    "site.shell.home.tile.portalAccess.sub": "நோயாளி செய்திகள், மற்றும் நோயாளிகள் மற்றும் குடும்பத்தினருக்கான பதிவு அணுகல்",
    "site.shell.home.tile.maik.title": "MaiK கிளினிக்கல் AI",
    "site.shell.home.tile.maik.sub": "கட்டுப்படுத்தப்பட்ட சுருக்கங்கள் மற்றும் வரைவு குறிப்புகள், எப்போதும் உங்களால் மதிப்பாய்வு செய்யப்படுபவை",
    "site.shell.home.tile.admin.title": "நிர்வாக மையம்",
    "site.shell.home.tile.admin.sub": "வார்டுகள், படுக்கைகள், துறைகள், அறைகள், பணியாளர்கள் மற்றும் பாத்திரங்கள்",
    "site.shell.home.tile.audit.title": "தணிக்கை மற்றும் பாதுகாப்பு",
    "site.shell.home.tile.audit.sub": "பதிவு மாற்றங்கள், அவசர அணுகல், மூல மானியங்கள், சேவை ஆரோக்கியம்",
