    "site.abdm.loadFailedLead": "ABDM சுயவிவரத்தை ஏற்ற முடியவில்லை:",
    "site.abdm.loadFailedTrail": ". இது அமைக்கப்படாததற்குச் சமம் அல்ல.",
    "site.abdm.intro1": "இந்த மருத்துவமனை சுகாதார வசதி பதிவேட்டில் தன்னை பதிவுசெய்து, StewardMD பாலத்திற்கான Software Linkage-ஐ அழுத்தவும்; ABDM பின்னர் அதன் HIP ID-ஐக் காட்டும். இந்த கார்டில் எதுவும் இன்னும் ABDM-ஐத் தொடர்புகொள்ளவில்லை.",
    "site.abdm.intro2": "நோயாளி பின்னர் சம்மதத்தை வாபஸ் பெற்றாலும், ABDM இலிருந்து இந்த மருத்துவமனை பெறுகின்ற பதிவுகள், அந்தச் சம்மதத்தின் கீழ் பெறப்பட்டதாகக் குறிக்கப்பட்டு, சார்ட்டில் இருக்கும்.",
    "site.abdm.regionNote": "ABDM இந்தியாவில் உள்ள ஒரு மருத்துவமனைக்கு பொருந்தும். இந்த மருத்துவமனையின் நாடு இந்தியா இல்லை.",
