    "site.admin.hospital.countryNote": "நாடு செல்லுபடியாகும் தொலைபேசி எண் எது என்பதையும், இனிமேல் வெப்பநிலை பதிவு செய்யப்படும் அலகையும் தீர்மானிக்கிறது. ஏற்கனவே பதிவு செய்யப்பட்ட அளவீடுகள் அவை பதிவு செய்யப்பட்ட அலகிலேயே இருக்கும்.",
