    "site.admin.maik.note": "MaiK-ஐ இயக்குவது மேலே பட்டியலிடப்பட்ட வழங்குநர்களைப் பயன்படுத்துகிறது. சூழலில் அதன் சான்றளிப்பு விசை (Credential-ன் கீழ் பெயரிடப்பட்டது) இருக்கும்போது மட்டுமே கிளவுட் வழங்குநர் பதிலளிக்கும். இரண்டாவது ஸ்விட்ச் ஆன் செய்யப்பட்டிருக்கும் போது மட்டுமே நோயாளி தரவு மருத்துவமனையை விட்டு வெளியேறும். MaiK-ன் மருத்துவ உள்ளடக்கம் கையொப்பமிடப்படவில்லை.",
