    "site.admin.security.anchor.disagree": "வெளிப்புற நகல்கள் வேறுபடுகின்றன",
    "site.admin.security.tellGovernance": "தகவல் ஆளுமை தலைவரிடம் தெரிவிக்கவும். மீட்டெடுக்கவோ அல்லது மீண்டும் இறக்குமதி செய்யவோ வேண்டாம்.",
    "site.admin.security.restoreNote": "தரவுத்தளம் வேண்டுமென்றே மீட்டெடுக்கப்பட்டால் (எடுத்துக்காட்டாக ஒரு குறிப்பிட்ட நேர மீட்டமைப்பு), இந்த அறிக்கை எதிர்பார்க்கப்படுகிறது மற்றும் அங்கீகரிக்கப்படும் வரை இருக்கும். இந்த மருத்துவமனையின் உரிமையாளர் மட்டுமே முறையான மீட்டமைப்பை, ஒரு காரணம் மற்றும் சம்பவக் குறிப்புடன் அங்கீகரிக்க முடியும். யாராலும் விளக்க முடியாத வேறுபாட்டை அங்கீகரிக்க வேண்டாம்: முதலில் தகவல் ஆளுமை தலைவரிடம் கேட்கவும்.",
    "site.admin.security.ackPrevious.rewritten": "தரவுத்தளத்திலிருந்து வேறுபட்டது",
    "site.admin.security.ackPrevious.truncated": "செயலிக்கு கீழே நீக்கப்பட்ட வரிசைகளைக் காட்டியது",
    "site.admin.security.ackRestore": "மீட்டமைப்பு அங்கீகரிக்கப்பட்டது",
    "site.admin.security.ackLine": "{by} என்பவர் {at} அன்று ஒரு முறையான மீட்டமைப்பை அங்கீகரித்தார் (சம்பவம் {incident}). அங்கீகாரத்திற்கு முன் வெளிப்புற நகல் {previous}",
    "site.admin.security.ackPreviousFallback": "நிலை {status} என புகாரளிக்கப்பட்டது",
