    "site.admin.security.atChainedRow": "சங்கிலி வரிசை {n} இல்",
    "site.admin.security.reasonGiven": "அளிக்கப்பட்ட காரணம்:",
    "site.admin.security.ackArchiveNote": "இந்த அங்கீகாரத்திற்கு முந்தைய ஆங்கர் பதிவு ஒரு காப்பகமாக வைக்கப்படுகிறது மற்றும் ஒருபோதும் நீக்கப்படாது. இந்த புள்ளிக்குக்குப் பிறகு ஏற்படும் புதிய வேறுபாடு மீண்டும் புகாரளிக்கப்படும்.",
    "site.admin.security.ackFormTitleOrg": "மருத்துவமனை நிகழ்வு பதிவின் முறையான மீட்டமைப்பை அங்கீகரிக்கவும்",
    "site.admin.security.ackFormTitle": "முறையான மீட்டமைப்பை அங்கீகரிக்கவும்",
    "site.admin.security.ackFormIntro": "இது தற்போதைய வெளிப்புற நகலைக் காப்பகப்படுத்தி, புதிய வரிசையிலிருந்து மீண்டும் தொடங்குகிறது, மேலும் உங்கள் பெயரின் கீழ் தணிக்கைப் பாதையில் அங்கீகாரத்தைப் பதிவுசெய்கிறது. மீட்டமைப்பு திட்டமிடப்பட்டு, கீழே உள்ள சம்பவக் குறிப்பின் கீழ் எழுதப்பட்டால் மட்டுமே இதைச் செய்ய வேண்டும். காரணத்தில் நோயாளியின் விவரங்களை ஒருபோதும் இட வேண்டாம்.",
    "site.admin.security.whyRestored": "தரவுத்தளம் ஏன் மீட்டெடுக்கப்பட்டது (குறைந்தது 20 எழுத்துகள்)",
    "site.admin.security.whyRestoredPlaceholder": "திட்டமிடப்பட்ட குறிப்பிட்ட நேர மீட்டமைப்புக்குப் பிறகு...",
    "site.admin.security.incidentRef": "சம்பவக் குறிப்பு",
    "site.admin.security.reviewAck": "அங்கீகாரத்தை மதிப்பாய்வு செய்யவும்",
    "site.admin.security.checkBeforeConfirming": "உறுதிப்படுத்தும் முன் சரிபார்க்கவும்.",
    "site.admin.security.ackingOrg": "மருத்துவமனை நிகழ்வு பதிவின் முறையான மீட்டமைப்பை நீங்கள் அங்கீகரிக்கிறீர்கள்.",
