    "site.admin.security.back": "பின்செல்",
    "site.admin.security.integrityNoResult": "சரிபார்க்கப்படவில்லை: ஒருமைப்பாடு முடிவு எதுவும் திரும்பப் பெறப்படவில்லை. இது தணிக்கைப் பதிவு அப்படியே இருப்பதற்குச் சமம் இல்லை.",
    "site.admin.security.chainedRow": "சங்கிலித் தொடர் வரிசை",
    "site.admin.security.expected": "எதிர்பார்க்கப்பட்டது",
    "site.admin.security.found": "கண்டறியப்பட்டது",
    "site.admin.security.integrityNote": "ஒவ்வொரு தணிக்கை வரிசையும் ஒரு ஹேஷ் மூலம் அதற்கு முந்தைய வரிசையுடன் இணைக்கப்பட்டுள்ளது, எனவே தரவுத்தளத்திலேயே செய்யப்பட்ட மாற்றம் அல்லது நீக்கம் இங்கே காட்டப்படும். புதிய வரிசைகள் ஒவ்வொரு முறையும் சரிபார்க்கப்படும். மணிக்கு ஒருமுறை புதிய வரிசை எண் தரவுத்தளத்திற்கு வெளியேயுள்ள இரண்டு சேமிப்பகங்களுக்கும் (KV மற்றும் Firestore) நகலெடுக்கப்பட்டு இங்கே ஒப்பிடப்படுகிறது, மேலும் அந்த இரண்டு நகல்களும் ஒன்றுடன் ஒன்று ஒப்பிடப்படுகின்றன. இது இயக்கப்படுவதற்கு முன்பு எழுதப்பட்ட வரிசைகள் இணைக்கப்படவில்லை மற்றும் சரிபார்க்க முடியாது.",
    "site.admin.export.status.running": "இயங்குகிறது",
