    "site.admin.export.status.expired": "காலாவதியானது, கோப்புகள் நீக்கப்பட்டன",
    "site.admin.export.title": "தரவு ஏற்றுமதி (FHIR)",
    "site.admin.export.intro": "இந்த மருத்துவமனையின் பதிவை பின்னணியில் FHIR R4 NDJSON ஆக, ஒரு வள வகைக்கு ஒரு கோப்பு வீதம் ஏற்றுமதி செய்கிறது. ஒரு நேரத்தில் ஒரு ஏற்றுமதி இயங்கும். இந்தக் கோப்புகள் இங்கிருந்தோ அல்லது FHIR Bulk Data API ($export-status) மூலமாகவோ இந்த மருத்துவமனையின் அனுமதியுடன் பதிவிறக்கப்படும்; ஒவ்வொரு பதிவிறக்கமும் தணிக்கைப் பதிவில் பதிவுசெய்யப்படும், மேலும் கோப்புகள் 24 மணிநேரத்திற்குப் பிறகு நீக்கப்படும்.",
    "site.admin.export.loadFailedLead": "ஏற்றுமதிகளை ஏற்ற முடியவில்லை",
    "site.admin.export.notSameAsNone": "இது எதுவும் இல்லை என்பதற்குச் சமம் இல்லை.",
