    "site.admin.fhir.serverTitle": "FHIR சேவையகம்",
    "site.admin.fhir.serverIntro": "இந்த மருத்துவமனையின் FHIR R4 API பிற அமைப்புகளுக்கு என்ன அறிவிக்கிறது என்பது. ஒரு நோயாளியின் சர்வதேச நோயாளி சுருக்கம் வார்டில் உள்ள அவர்களின் அட்டவணையில் இருந்து திறக்கிறது.",
