    "site.admin.webhooks.status.active": "செயலில் உள்ளது",
    "site.admin.webhooks.status.disabled": "முடக்கப்பட்டது",
    "site.admin.webhooks.status.autoDisabled": "தொடர்ச்சியான தோல்விகளுக்குப் பிறகு முடக்கப்பட்டது",
    "site.admin.webhooks.intro1": "ஒரு webhook என்பது இங்கு ஏதோ நடந்தது என்பதை மற்றொரு அமைப்பிற்கு தெரிவிக்கிறது. இது நிகழ்வு வகை மற்றும் अस्पஷ்டமான id ஐ மட்டுமே கொண்டுள்ளது: பெயர், எண், பரிசோதனை அல்லது மதிப்பு ஒருபோதும் இல்லை.",
    "site.admin.webhooks.intro2": "பெறும் அமைப்பு WardSynQ FHIR API மூலம் தனது சொந்த SMART அணுகலைக் கொண்டு விவரங்களைப் படிக்கிறது, அங்கு இந்த மருத்துவமனையின் அனுமதிகள் மற்றும் தணிக்கைப் பதிவு பொருந்தும்.",
    "site.admin.webhooks.intro3": "ஒவ்வொரு அழைப்பும் கையொப்பமிடப்பட்டுள்ளது: X-WardSynQ-Signature என்பது X-WardSynQ-Timestamp, ஒரு புள்ளி மற்றும் உடல் பகுதி ஆகியவற்றின் HMAC-SHA256 ஆகும், இது எண்ட்பாயிண்டின் இரகசியத்தைக் கொண்டுள்ளது.",
    "site.admin.webhooks.loading": "Webhooks ஏற்றப்படுகின்றன...",
