    "site.admin.webhooks.copyNow": "இப்போதே நகலெடுக்கவும். இது மீண்டும் காட்டப்படாது. முந்தைய இரகசியம் 24 மணிநேரத்திற்குத் தொடர்ந்து செயல்படும், எனவே பெறும் அமைப்பைப் புதுப்பிக்க முடியும்.",
