    "site.admin.smart.scope.none": "எதுவும் இல்லை",
    "site.admin.smart.title": "இணைக்கப்பட்ட ஆப்ஸ்கள் (SMART)",
    "site.admin.smart.intro1": "SMART on FHIR மூலமாக மருத்துவமனை தனது பதிவுகளைப் படிக்க அனுமதிக்கும் வெளி ஆப்ஸ்கள்: ஒரு கிளினிஷியன் பயன்படுத்தும் ஆப் (பொது), அல்லது சாவியுடன் கூடிய பதிவுசெய்த சிஸ்டம் (பேக்கெண்ட்).",
    "site.admin.smart.intro2": "பதிவுசெய்தல் என்பது அனுமதிக்கப்பட்ட பட்டியல்: இங்கு குறிப்பிடப்படாத ஒரு ஆப்பிற்கு எதுவும் கிடைக்காது, மேலும் ஒன்றை நீக்குவது அதன் டோக்கன்களை உடனடியாக நிறுத்தும். ஸ்விட்சை ஆஃப் செய்வது ஒவ்வொரு ஆப்பிற்கும் SMART கதவை மூடுகிறது.",
    "site.admin.smart.loading": "இணைக்கப்பட்ட ஆப்ஸ்கள் ஏற்றப்படுகின்றன...",
    "site.admin.smart.loadFailedLead": "இணைக்கப்பட்ட ஆப்ஸ்களை ஏற்ற முடியவில்லை:",
    "site.admin.smart.notSameAsNone": "இது எதுவும் இல்லை என்பதற்குச் சமம் அல்ல.",
