    "site.maik.governedNote": "MaiK பதிவிலிருந்து வரைவு செய்கிறது மற்றும் ஒரு மருத்துவ மருத்துவர் அவற்றை ஏற்கும் வரை அதன் பதில்கள் கையொப்பமிடப்படாமல் இருக்கும். ஒவ்வொரு தொடர்பும் அதன் மாதிரி, ஆதாரங்கள் மற்றும் உங்கள் மதிப்பாய்வுடன் பதிவில் எழுதப்படுகிறது. இந்த உருவாக்கத்தில் உள்ள மருத்துவ உள்ளடக்கம் இன்னும் மருத்துவமனைக் குழுவால் ஒப்புதல் அளிக்கப்படவில்லை.",
