    "site.maik.notConfigured": "இந்த மருத்துவமனைக்கு MaiK அமைக்கப்படவில்லை. ஒரு மருத்துவமனை நிர்வாகி Admin Center, MaiK clinical AI இல் அதை ஆன் செய்து மாதிரி வழங்குநரை அங்கீகரிக்கிறார். இது இல்லாமல் சார்ட்டிங் மற்றும் பாதுகாப்பு சோதனைகள் செயல்படும்.",
