    "site.security.accountProviderNote": "இந்தப் பக்கம் மருத்துவமனை ஊழியர்களின் உள்நுழைவுக்கானது (மருத்துவமனை கோட், ஊழியர் ID மற்றும் PIN, அல்லது ஊழியர் மின்னஞ்சல்). StewardMD கணக்கு அதன் சொந்த கணக்கு வழங்குநரைக் கொண்டு இருபடி உள்நுழைவை அமைக்கிறது.",
