    "site.labAn.notSameAsNone": "எதுவும் இல்லை என்பதற்கு இது சமமல்ல.",
    "site.labAn.intro": "பகுப்பாய்விகள் ஆய்வகத்தின் நெட்வொர்க்கில் உள்ள கணினியில் இயங்கும் சிறிய நிரலான StewardMD பகுப்பாய்வி இணைப்பி (connect-agent/analyser) மூலம் இணைகின்றன. அவற்றின் முடிவுகள் ஆய்வகப் பலகைக்கு (Laboratory board) வருகின்றன, அதைத் தொழில்நுட்ப வல்லுநர் (technologist) சரிபார்த்து வெளியிட வேண்டும்; எதுவுமே தானாகவே வெளியாகாது.",
