    "site.admin.staff.roleNote.dietitian": "Chart-ஐப் பார்க்கிறது, உணவு முறைகளை ஆர்டர் செய்கிறது மற்றும் மாற்றுகிறது, உணவு ரவுண்டுகளைப் பார்க்கிறது.",
    "site.admin.staff.roleNote.kitchen": "உணவு ரவுண்டுகள் மட்டுமே: பெயர், படுக்கை, diet, nil by mouth மற்றும் ஒவ்வாமைகள். தட்டுகள் தயாரிக்கப்பட்டு விநியோகிக்கப்பட்டதாகக் குறிக்கிறது.",
    "site.admin.staff.roleNote.cssd": "கருவித் தொகுப்புகள், steriliser சுமைகள் மற்றும் அவற்றின் குறிகாட்டிகள், தியேட்டருக்கு வழங்குதல். Chart அணுகல் இல்லை.",
    "site.admin.staff.roleNote.housekeeping": "துப்புரவுப் பணிகளை எடுத்து முடிக்கிறது. ஒரு மேற்பார்வையாளர் அவற்றை ஆய்வு செய்கிறார். Chart அணுகல் இல்லை.",
